// Derivador universal: lo que se puede saber SIN preguntarle a ningun portal.
//
// Cada portal tiene su scraper y su enriquecedor, y esta bien: cada uno habla
// un idioma distinto. Pero hay reglas que no dependen del portal -la etiqueta
// de la DGT sale del combustible y el año, y los kW son los CV divididos entre
// 1,35962- y ponerlas en once sitios garantiza once versiones distintas.
//
// Aqui van una sola vez, para los once.

const filas = $input.all().map(function (x) { return x.json; });
if (!filas.length) return [{ json: { sql: null, count: 0 } }];

function esc(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}

// Un hibrido de verdad deja rastro en el nombre comercial. Se exige ese rastro
// antes de dar ECO por el campo `fuel`, y no por desconfianza teorica: Autohero
// declara 'Híbrido' un Opel Crossland 1.2 Turbo y un Seat Ateca 1.0 TSI, que
// son gasolina pura. Con esta comprobacion su coincidencia con la etiqueta que
// el propio portal publica sube del 51% al 93%.
const MARCA_HIBRIDO = /\b(h[ií]brid\w*|hybrid\w*|hev|mhev|mild.?hybrid|48\s*v|e-?tech|e-?skyactiv|blue.?hybrid)\b/i;

// El mild hybrid lleva ECO aunque el combustible diga Diesel o Gasolina: el
// '48V' o el 'MHEV' viven en el titulo, no en el campo. Sin esto, 2.300 Kia
// Sportage y Hyundai Tucson se quedaban en C cuando el portal les da ECO.
const MARCA_MHEV = /\b(mhev|mild.?hybrid|48\s*v)\b/i;

// La etiqueta ambiental es una REGLA de la DGT, no un dato del anuncio:
//
//   Cero  electrico puro.
//   ECO   hibrido no enchufable, mild hybrid, GLP y GNC.
//   C     gasolina desde 2006, diesel desde 2016.
//   B     gasolina 2001-2005, diesel 2006-2014.
//   NONE  gasolina anterior a 2001, diesel anterior a 2006.
//
// Contrastada contra las 302.055 ofertas en las que algun portal ya publico la
// etiqueta: coincide en el 96%. Y donde no coincide suele fallar el portal -
// coches.com da 'B' a diesel de 2016, que ya son Euro 6, en 799 ofertas.
//
// Los casos de frontera se dejan VACIOS a proposito. Vacio significa 'no lo
// sabemos', que es la verdad, y es lo unico que no engaña a nadie:
//   - Hibrido enchufable: Cero o ECO segun la autonomia electrica (>=40 km), y
//     esa autonomia no la tenemos en ningun portal.
//   - Diesel de 2015: el Euro 6 entro en septiembre, y con el año solo no se
//     sabe de que lado cae la matriculacion.
function etiquetaDGT(fuel, year, texto) {
  const f = String(fuel || '').toLowerCase();
  const y = Number(year);
  const t = String(texto || '');
  if (!f) return '';
  if (f.indexOf('eléctric') !== -1 || f.indexOf('electric') !== -1) return '0 Emisiones';
  if (f.indexOf('enchufable') !== -1) return '';
  if (f.indexOf('híbrido') !== -1 || f.indexOf('hibrido') !== -1) return MARCA_HIBRIDO.test(t) ? 'ECO' : '';
  if (f.indexOf('gas') !== -1 && f.indexOf('gasolina') === -1) return 'ECO';
  if (!y || y < 1950 || y > 2027) return '';
  if (MARCA_MHEV.test(t)) return 'ECO';
  if (f.indexOf('gasolina') !== -1) {
    if (y >= 2006) return 'C';
    if (y >= 2001) return 'B';
    return 'NONE';
  }
  if (f.indexOf('diesel') !== -1 || f.indexOf('diésel') !== -1) {
    if (y >= 2016) return 'C';
    if (y === 2015) return '';
    if (y >= 2006) return 'B';
    return 'NONE';
  }
  return '';
}

// --- Color: un vocabulario, no un vertedero ---------------------------------
//
// La columna tenia 835 valores distintos para 721.419 filas, y trece de ellos
// cubrian el 95%. El resto era el mismo color escrito de otra forma -'Blanco'
// 199.500 y 'blanco' 37.813- mas una cola de 677 nombres comerciales que suman
// 952 filas: AZUL CAVANSITA, Azul Navarra (metalizado), ATLAS WHITE.
//
// Esta es la UNICA regla del derivador que PISA un valor existente, y conviene
// decir por que se acepta: no afirma nada nuevo, escribe lo mismo de una sola
// manera. Medido antes de aplicarlo: de las 110.039 filas que cambian, 107.598
// cambian solo de forma y no pierden nada, y 2.441 pierden el matiz comercial
// -ATLAS WHITE pasa a Blanco-, que son nombres de una a cuatro filas cada uno.
//
// Gana el color que aparezca ANTES en el texto, no el primero de la lista: en
// 'Gris Plata' manda Gris porque es lo que se lee primero.
const COLORES = [
  ['blanco', 'Blanco'], ['gris', 'Gris'], ['negro', 'Negro'], ['azul', 'Azul'],
  ['rojo', 'Rojo'], ['plata', 'Plata'], ['verde', 'Verde'], ['naranja', 'Naranja'],
  ['marron', 'Marrón'], ['beige', 'Beige'], ['granate', 'Granate'],
  ['amarillo', 'Amarillo'], ['burdeos', 'Burdeos'], ['dorado', 'Dorado'],
  ['violeta', 'Violeta'], ['morado', 'Morado'], ['plateado', 'Plata'],
  ['blanca', 'Blanco'], ['negra', 'Negro'], ['roja', 'Rojo'], ['bronce', 'Bronce'],
  ['rosa', 'Rosa'], ['oro', 'Dorado'], ['turquesa', 'Azul'],
  // Los concesionarios de importacion escriben el nombre en ingles.
  ['white', 'Blanco'], ['black', 'Negro'], ['silver', 'Plata'], ['grey', 'Gris'],
  ['gray', 'Gris'], ['blue', 'Azul'], ['red', 'Rojo'], ['green', 'Verde'],
  ['yellow', 'Amarillo'], ['brown', 'Marrón'], ['orange', 'Naranja']
];

// Lo que ocupa la columna del color sin ser un color. 'otro' son 3.946 filas.
const NO_ES_COLOR = /^(otro|otros|con|sin|pendiente|no aplica|-+|n\/?d|sin\s+(designar|especificar|definir|color))$/i;

function normalizaColor(v) {
  const bruto = String(v || '').trim();
  if (!bruto || NO_ES_COLOR.test(bruto)) return '';
  const s = bruto.toLowerCase()
    .replace(/[áàä]/g, 'a').replace(/[éèë]/g, 'e').replace(/[íìï]/g, 'i')
    .replace(/[óòö]/g, 'o').replace(/[úùü]/g, 'u');
  let mejor = null, pos = 1e9;
  for (const par of COLORES) {
    const i = s.search(new RegExp('\\b' + par[0]));
    if (i >= 0 && i < pos) { pos = i; mejor = par[1]; }
  }
  return mejor || '';
}

const vals = [];
for (const o of filas) {
  // El texto que se mira: lo que el portal escribio del coche, mas la
  // descripcion si la tenemos guardada.
  const texto = [o.title, o.version, o.descripcion].filter(Boolean).join(' ');

  const etiqueta = etiquetaDGT(o.fuel, o.year, texto);

  // Potencia: si hay una unidad y falta la otra, se convierte. No se inventa
  // ninguna de las dos: solo se completa el par.
  let cv = null, kw = null;
  if (o.power_cv != null && o.power_kw == null) kw = Math.round(Number(o.power_cv) / 1.35962);
  if (o.power_kw != null && o.power_cv == null) cv = Math.round(Number(o.power_kw) * 1.35962);

  // Cilindrada y traccion salen del nombre comercial igual en todos los
  // portales: un 'quattro' es un quattro lo publique quien lo publique.
  let cc = null;
  if (!o.displacement) {
    const m = texto.match(/\b(\d)[.,](\d)\b/);
    if (m) { const v = Number(m[1] + '.' + m[2]); if (v >= 0.6 && v <= 8.0) cc = m[1] + '.' + m[2]; }
  }

  // El color, normalizado. Solo cuenta si CAMBIA algo: si ya esta bien escrito
  // se deja en blanco para que el guardian de abajo no toque la fila.
  const colorNuevo = normalizaColor(o.color);
  const colorCambia = String(o.color || '') !== colorNuevo;

  let traccion = '';
  if (!o.traction) {
    const m = texto.match(/\b(4x4|awd|quattro|4motion|xdrive|4matic|4wd|allrad|4drive|rwd|fwd)\b/i);
    if (m) { const v = m[1].toLowerCase();
      traccion = v === 'rwd' ? 'Trasera' : v === 'fwd' ? 'Delantera' : 'Total'; }
  }

  if (!etiqueta && cv == null && kw == null && !cc && !traccion && !colorCambia) continue;

  vals.push('(' + esc(o.id) + ', ' + esc(etiqueta) + '::varchar, ' +
    (cv != null ? cv : 'NULL') + '::int, ' + (kw != null ? kw : 'NULL') + '::int, ' +
    esc(cc) + '::varchar, ' + esc(traccion) + '::varchar, ' +
    (colorCambia ? esc(colorNuevo) : 'NULL') + '::varchar)');
}

if (!vals.length) return [{ json: { sql: null, count: 0 } }];

// COALESCE en todos: esto SOLO rellena huecos. Lo que dijo el portal manda
// siempre, aunque la regla opine otra cosa -y a veces la regla tiene razon, pero
// no es este el sitio para discutirselo al portal.
//
// El '' final en environmental_label no es adorno: la columna es NOT NULL con
// defecto vacio, y sin el una fila sin etiqueta calculada revienta el UPDATE
// entero, con el lote completo dentro.
const sql =
  'UPDATE moveadvisor_market_offers t SET ' +
    "environmental_label = COALESCE(NULLIF(t.environmental_label,''), NULLIF(d.etiqueta,''), ''), " +
    'power_cv = COALESCE(t.power_cv, d.cv), ' +
    'power_kw = COALESCE(t.power_kw, d.kw), ' +
    "displacement = COALESCE(NULLIF(t.displacement,''), NULLIF(d.cc,'')), " +
    "traction = COALESCE(NULLIF(t.traction,''), NULLIF(d.traccion,'')), " +
    // El color SI se pisa, y es la unica columna asi. Ver normalizaColor().
    "color = CASE WHEN d.color_nuevo IS NULL THEN t.color ELSE d.color_nuevo END, " +
    'updated_at = NOW() ' +
  'FROM (VALUES ' + vals.join(', ') + ') AS d(id, etiqueta, cv, kw, cc, traccion, color_nuevo) ' +
  'WHERE t.id = d.id AND (' +
    // Solo se tocan las filas en las que algo va a cambiar de verdad.
    //
    // Sin esto, como este workflow no lleva marca de 'ya intentado' -para poder
    // repetirlo cuando mejore una regla- volveria a escribir las mismas filas
    // cada dia, poniendo updated_at = NOW() aunque el COALESCE no cambiara nada.
    // Eso deja miles de ofertas pareciendo modificadas cada mañana y vacia de
    // significado la unica columna que dice cuando cambio algo.
    "(NULLIF(t.environmental_label,'') IS NULL AND NULLIF(d.etiqueta,'') IS NOT NULL) OR " +
    '(t.power_cv IS NULL AND d.cv IS NOT NULL) OR ' +
    '(t.power_kw IS NULL AND d.kw IS NOT NULL) OR ' +
    "(NULLIF(t.displacement,'') IS NULL AND NULLIF(d.cc,'') IS NOT NULL) OR " +
    "(NULLIF(t.traction,'') IS NULL AND NULLIF(d.traccion,'') IS NOT NULL) OR " +
    "(d.color_nuevo IS NOT NULL AND COALESCE(t.color,'') <> d.color_nuevo)" +
  ')';

return [{ json: { sql: sql, count: vals.length } }];
